  /**
   * Unique symbol used as the key for the `PopulatedDocumentMarker`. Using a unique symbol
   * means the marker is invisible at runtime and cannot collide with any user-defined property.
   */
  const populatedDocumentMarker: unique symbol;

  /**
   * A type marker attached to populated document types. It carries both the populated raw
   * document type and the original depopulated raw document type as invisible metadata via a
   * unique symbol key. This allows `toObject()` / `toJSON()` overloads to be resolved based on
   * whether a document has been populated, and to recover the populated / depopulated shapes.
   *
   * Strip the marker externally via `Omit<typeof doc, keyof PopulatedDocumentMarker<any, any>>`.
   */
  export type PopulatedDocumentMarker<PopulatedRawDocType, DepopulatedRawDocType> = {
    [populatedDocumentMarker]: {
      populated: PopulatedRawDocType;
      depopulated: DepopulatedRawDocType;
    };
  };

  /**
   * The result type of a populate operation. Combines the document with the populated paths
   * (via `MergeType`, which preserves the document methods) and attaches a
   * `PopulatedDocumentMarker` carrying both the populated and depopulated raw doc types.
   */
  export type PopulateDocumentResult<Doc, Paths, PopulatedRawDocType, DepopulatedRawDocType = PopulatedRawDocType> =
    MergeType<Doc, Paths> & PopulatedDocumentMarker<PopulatedRawDocType, DepopulatedRawDocType>;

  /**
   * Extracts the plain object type from a Document intersection type. If `T` extends some
   * `ObjectType & Document`, returns `FlatRecord<ObjectType>`; otherwise returns `T`.
   */
  export type ExtractDocumentObjectType<T> = T extends Document<any, any, infer DocType, any, any>
    ? FlatRecord<DocType>
    : T;

  /**
   * Recursive helper that converts a populate `Paths` type (which may contain Document instances,
   * DocumentArrays, plain arrays, or nested objects) into a plain raw document type suitable for
   * use as the populated raw doc type.
   */
  export type PopulatePathToRawDocType<T> = {
    [K in keyof T]: T[K] extends Types.DocumentArray<infer ItemType>
      ? ExtractDocumentObjectType<ItemType>[]
      : T[K] extends Document
        ? ExtractDocumentObjectType<T[K]>
        : T[K] extends Array<infer ItemType>
          ? (ItemType extends Document ? ExtractDocumentObjectType<ItemType> : PopulatePathToRawDocType<ItemType>)[]
          : T[K] extends Record<string, any>
            ? PopulatePathToRawDocType<T[K]>
            : T[K];
  };

  /**
   * Helper type that computes the "raw doc type" for a document after population by merging
   * (unpacking intersection of) `RawDocType` with the POJO form of the populated paths.
   */
  export type PopulatedPathsDocumentType<RawDocType, Paths> =
    UnpackedIntersection<RawDocType, PopulatePathToRawDocType<Paths>>;
